(* [comment removed for export] *)
Definition writes_ok (A : astate) (ws : list fct) : Prop :=
  forall w x, In w ws -> f_a w <= x < f_a w + f_n w ->
    (dom A x \/ exists k, cvalid k /\ caddr k <= x < caddr k + clen k) /\
    (forall p n, a_live A p = Some n -> ~ (p <= x < p + n)).

